<script>
(function(){
  // 3D stage parallax (mouse / touch)
  var stage=document.getElementById('stage'), wrap=document.querySelector('.scene-wrap');
  function tilt(x,y){ stage.style.setProperty('--ry',(-16 + x*18)+'deg'); stage.style.setProperty('--rx',(10 - y*12)+'deg'); }
  window.addEventListener('mousemove',function(e){ tilt(e.clientX/innerWidth-.5, e.clientY/innerHeight-.5); });
  window.addEventListener('deviceorientation',function(e){ if(e.gamma!=null) tilt(e.gamma/60, (e.beta-40)/80); });

  // browser auto-scroll distance
  var img=document.getElementById('fullimg'), vp=document.getElementById('vp');
  function setScroll(){ var d=img.offsetHeight-vp.offsetHeight; if(d>0) img.style.setProperty('--scroll',(-d)+'px'); }
  if(img.complete) setScroll(); else img.addEventListener('load',setScroll);
  window.addEventListener('resize',setScroll);

  // 3D card stack
  var cards=[].slice.call(document.querySelectorAll('.scard')), dots=[].slice.call(document.querySelectorAll('#stDots button'));
  var tEl=document.getElementById('stTitle'), dEl=document.getElementById('stDesc'), active=0, timer;
  function layout(){
    var n=cards.length;
    cards.forEach(function(c,i){
      var o=(i-active+n)%n;
      c.style.transform='translateY('+(-o*34)+'px) translateZ('+(-o*110)+'px) rotateX('+(o?6:0)+'deg) rotateY('+(o? -4*o:0)+'deg)';
      c.style.opacity= o===0?1:(o===1?.7:.4);
      c.style.filter= o===0?'none':'brightness(.6) saturate(.7)';
      c.style.zIndex= n-o;
    });
    dots.forEach(function(d,i){ d.classList.toggle('on',i===active); });
    tEl.textContent=cards[active].dataset.title; dEl.textContent=cards[active].dataset.desc;
  }
  function go(i){ active=(i+cards.length)%cards.length; layout(); clearInterval(timer); timer=setInterval(function(){go(active+1)},5000); }
  cards.forEach(function(c,i){ c.addEventListener('click',function(){ go(active+1); }); });
  dots.forEach(function(d,i){ d.addEventListener('click',function(){ go(i); }); });
  go(0);

  // 3D tilt cards + spotlight
  document.querySelectorAll('.bcard').forEach(function(el){
    el.addEventListener('mousemove',function(e){
      var r=el.getBoundingClientRect(), x=(e.clientX-r.left)/r.width, y=(e.clientY-r.top)/r.height;
      el.style.transform='rotateY('+((x-.5)*14)+'deg) rotateX('+((.5-y)*12)+'deg) translateZ(10px)';
      el.style.setProperty('--mx',x*100+'%'); el.style.setProperty('--my',y*100+'%');
    });
    el.addEventListener('mouseleave',function(){ el.style.transform=''; });
  });

  // 3D tech ring layout
  var rc=[].slice.call(document.querySelectorAll('.ring3d .rc')), R=Math.max(150, rc.length*19);
  rc.forEach(function(c,i){ c.style.transform='rotateY('+(i*360/rc.length)+'deg) translateZ('+R+'px)'; });

  // reveal + counters
  function count(el){
    var to=+el.dataset.to, t0=null;
    function step(t){ if(!t0)t0=t; var p=Math.min((t-t0)/1400,1); el.textContent=Math.round(to*(1-Math.pow(1-p,3))); if(p<1)requestAnimationFrame(step); }
    requestAnimationFrame(step);
  }
  var io=new IntersectionObserver(function(es){
    es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('in'); e.target.querySelectorAll('[data-to]').forEach(count); io.unobserve(e.target);} });
  },{threshold:.15});
  document.querySelectorAll('.rv').forEach(function(el){ io.observe(el); });
})();
</script>
